package garden.xeno.symbolum.theories

import java.io.ByteArrayOutputStream
import java.nio.charset.StandardCharsets
import java.nio.file.{Files, Path, Paths}

import org.scalatest.flatspec.AnyFlatSpec
import org.scalatest.matchers.should.Matchers

/**
 * The commands the generated documents name in their own failure messages, run.
 *
 * == The gap this closes, measured rather than suspected ==
 *
 * The arrangement here has two halves: a generated artifact is committed and compared in the
 * pipeline against the live one, and it is regenerated by **one named command**. The first half is
 * well guarded — `LibrarySpec`, `RegisterSpec`, `TheoremsSpec`, `ExamplesSpec`, `GuideSpec` and
 * `FoundationSpec` each compare their document's generated region against what the code produces,
 * and each fails naming the command. The second half had nothing behind it at all.
 *
 * Read off the coverage report of a `clean coverage test coverageReport` run at `72739a0`, by
 * counting statements whose method is `main` or `run`: **eight entry points in this module, 94
 * statements, every one of them zero-invoked.** Not one of those commands had ever been executed
 * by a test. So a reader sent to run `Lemmas` by a red `LibrarySpec` was being sent to code no
 * test had run, at exactly the moment the document is known to be wrong.
 *
 * That is worse than it sounds because of **when** it is met, which is `Lemmas`'s own argument
 * about its document: the command is reached when somebody has just added a lemma and has least
 * appetite for finding out how the file is produced. A command that crashes there is met by the
 * person least willing to debug it.
 *
 * == What this asserts that the comparison specs do not ==
 *
 * They compare a **string** the generator computed against a **string** read from the document.
 * Everything between those two is untested: reading the path out of the arguments, reading the
 * file off disk, splicing the region into the surrounding prose, deciding whether anything
 * changed, and writing the bytes back. This drives `main` end to end over a temporary copy and
 * asserts the file that comes out is the committed one, byte for byte.
 *
 * Two runs per generator, and the second is the one that matters. Against an up-to-date copy the
 * command takes its "already what the code says" branch and **writes nothing**, so a test with
 * only that run would pass over a generator whose write is broken. So the region is perturbed
 * first, through the generator's own `Generated.spliced`, and then the command has to put it
 * back.
 *
 * == What it deliberately does not reach ==
 *
 * The failure arms. Every one of these commands answers a refusal with `System.err.println` and
 * `sys.exit(1)`, which from inside a test is not a failure to assert but a JVM that stops: the
 * suite would end mid-run and report nothing. They are not untested for it — the refusals
 * underneath are, as strings, by `RegisterSpec`'s marker cases and the `spliced` assertions beside
 * them. What is untested and stays untested is the `sys.exit` itself, which is the one statement
 * per command this file cannot reach and is named here rather than left to be found in a report.
 *
 * `Essay` is the eighth entry point and is not a document generator: it prints one page and writes
 * no file, so it is driven separately below, in all three of its arms.
 *
 * Nothing here writes inside the working tree. Every run is against a copy under the system
 * temporary directory, and the committed documents are read and never opened for writing, which
 * is the property that lets this run beside every other suite rather than in a checkout of its
 * own.
 */
class GeneratorCommandSpec extends AnyFlatSpec with Matchers {

  /** A generator, as this file needs it: what to call, where it writes, and a region to disturb. */
  private final case class Command(
    name: String,
    document: String,
    section: Generated,
    run: Array[String] => Unit
  )

  private val commands: Vector[Command] = Vector(
    Command("Lemmas", Lemmas.Document, Lemmas.Section, Lemmas.main),
    Command("Theorems", Theorems.Document, Theorems.Section, Theorems.main),
    Command("Examples", Examples.Document, Examples.Section, Examples.main),
    Command("Guide", Guide.Document, Guide.ClassicalTable, Guide.main),
    Command("Foundation", Foundation.Document, Foundation.TrustedBase, Foundation.main)
  )

  private def read(path: String): String =
    new String(Files.readAllBytes(Paths.get(path)), StandardCharsets.UTF_8)

  private def readFile(path: Path): String =
    new String(Files.readAllBytes(path), StandardCharsets.UTF_8)

  /** Run something that prints, keeping its output out of the suite's log and returning it. */
  private def quietly(body: => Unit): String = {
    val captured = new ByteArrayOutputStream()
    Console.withOut(captured)(body)
    captured.toString(StandardCharsets.UTF_8)
  }

  /** A copy of `content` under the temporary directory, removed when `body` is done with it. */
  private def inACopy(name: String, content: String)(body: Path => Unit): Unit = {
    val path = Files.createTempFile(s"symbolum-$name-", ".md")
    try {
      Files.write(path, content.getBytes(StandardCharsets.UTF_8))
      body(path)
    } finally {
      Files.deleteIfExists(path)
      ()
    }
  }

  /* ------------------------------------------------------------------ the five that write */

  "Each generator's command" should "leave an up-to-date document exactly as it found it" in {
    commands.foreach { command =>
      withClue(s"${command.name}: ") {
        val committed = read(command.document)

        inACopy(command.name, committed) { path =>
          val said = quietly(command.run(Array(path.toString)))

          readFile(path) shouldBe committed
          said should include("already what the code says")
        }
      }
    }
  }

  it should "put the region back when it has been disturbed, which is the run that writes" in {
    // The assertion that keeps the one above from being vacuous. That one drives the branch where
    // the command decides nothing changed and returns without touching the file, so it would pass
    // over a generator whose write path was broken or absent. Here the file on disk is wrong when
    // the command starts and right when it stops, and the difference is bytes written.
    //
    // **Observed failing, 2026-09-18, and the split is what was observed.** The one statement
    // these five commands write through is `Files.write` in `Generated.rewrite`; removed, this
    // assertion goes red and the one above it stays **green**, which is the claim this pair of
    // tests makes about itself rather than an argument for it. The register's assertion stayed
    // green too, and that is the perturbation being local rather than the guard being weak: it
    // writes through a `Files.write` of its own, which is the same reason it is driven separately
    // below.
    commands.foreach { command =>
      withClue(s"${command.name}: ") {
        val committed = read(command.document)
        val disturbed = command.section
          .spliced(committed, "this is not what the code says")
          .fold(why => fail(s"the section could not be disturbed: $why"), identity)

        disturbed should not be committed

        inACopy(command.name, disturbed) { path =>
          val said = quietly(command.run(Array(path.toString)))

          readFile(path) shouldBe committed
          said should include("rewritten")
        }
      }
    }
  }

  /* ------------------------------------------------------------------ the register, which is its own */

  /**
   * `Register` is the same claim and not the same code: it splices with markers of its own rather
   * than through a [[Generated]], because its rows carry attestations read off a second file. So
   * it is driven here by the same two runs and through its own API.
   */
  "The register's command" should "reproduce the committed document, from up to date and from disturbed" in {
    val committed = read(Register.Document)

    inACopy("register", committed) { path =>
      val said = quietly(Register.main(Array(path.toString)))

      readFile(path) shouldBe committed
      said should include("already what the code says")
    }

    val disturbed = Register
      .spliced(committed, "this is not what the code says")
      .fold(why => fail(s"the section could not be disturbed: $why"), identity)

    disturbed should not be committed

    inACopy("register", disturbed) { path =>
      val said = quietly(Register.main(Array(path.toString)))

      readFile(path) shouldBe committed
      said should include("rewritten")
    }
  }

  /* ------------------------------------------------------------------ the one that prints */

  /**
   * `Essay` writes no file: it prints one lemma's page, so what a run of it has to be checked
   * against is what it printed. All three arms, because the two that are not the happy one are
   * what a reader meets when they mistype a name or forget the argument, and both answer by
   * naming the command rather than by failing.
   */
  "The essay's command" should "print a page for a lemma, and name the command for anything else" in {
    val page = quietly(Essay.main(Array("ADD_SYM")))
    page should include("ADD_SYM")
    page should not include Essay.Command

    val unknown = quietly(Essay.main(Array("NOTHING_IS_CALLED_THIS")))
    unknown should include(Essay.Command)

    val nothing = quietly(Essay.main(Array.empty))
    nothing should include("one lemma at a time")
    nothing should include(Essay.Command)
  }
}
